'use client';

import { forwardRef, type ButtonHTMLAttributes } from 'react';
import './tactile-button.css';

export interface TactileButtonProps extends ButtonHTMLAttributes<HTMLButtonElement> {}

/** A raised key with a fixed hit area and a mechanical pressed surface. */
export const TactileButton = forwardRef<HTMLButtonElement, TactileButtonProps>(
  function TactileButton({ children, className = '', type = 'button', ...props }, ref) {
    return (
      <button {...props} ref={ref} type={type} className={`ac-tactile-button ${className}`.trim()}>
        <span className="ac-tactile-button__surface">
          <span className="ac-tactile-button__label">{children}</span>
          <svg width="18" height="18" viewBox="0 0 24 24" fill="none" aria-hidden="true" focusable="false">
            <path d="M19 5v9H5m5-5-5 5 5 5" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" />
          </svg>
        </span>
      </button>
    );
  },
);

.ac-tactile-button {
  --ac-tactile-surface: #e9a17f;
  --ac-tactile-ink: #33271f;
  --ac-tactile-base: #5f3a2c;
  --ac-tactile-line: #5f3a2c;
  position: relative;
  display: inline-grid;
  min-height: 56px;
  max-width: 100%;
  padding: 0 0 6px;
  border: 1px solid var(--ac-tactile-line);
  border-radius: var(--ac-tactile-radius, 7px);
  background: var(--ac-tactile-base);
  color: var(--ac-tactile-ink);
  font: inherit;
  font-size: 14px;
  line-height: 1.25;
  text-align: center;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
}
.ac-tactile-button,
.ac-tactile-button * { box-sizing: border-box; }
.ac-tactile-button__surface {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 24px;
  min-height: 48px;
  padding: 14px 22px;
  border-bottom: 1px solid var(--ac-tactile-line);
  border-radius: max(0px, calc(var(--ac-tactile-radius, 7px) - 1px));
  background: var(--ac-tactile-surface);
  font-weight: 600;
  pointer-events: none;
  transition: transform .18s cubic-bezier(.2, .8, .2, 1), background .18s;
}
.ac-tactile-button__label { min-width: 0; overflow-wrap: anywhere; }
.ac-tactile-button__surface svg { flex-shrink: 0; }
.ac-tactile-button:focus-visible { outline: 2px solid var(--ac-tactile-base); outline-offset: 5px; }
.ac-tactile-button:active:not(:disabled) .ac-tactile-button__surface { transform: translateY(6px); }
.ac-tactile-button:disabled { opacity: .45; cursor: not-allowed; }
@media (hover: hover) and (pointer: fine) {
  .ac-tactile-button:hover:not(:disabled):not(:active) .ac-tactile-button__surface { transform: translateY(2px); background: color-mix(in srgb, var(--ac-tactile-surface), white 7%); }
}
@media (prefers-reduced-motion: reduce) {
  .ac-tactile-button__surface { transition: none; transform: none !important; }
  .ac-tactile-button:active:not(:disabled) .ac-tactile-button__surface { background: color-mix(in srgb, var(--ac-tactile-surface), black 9%); }
}
